This is a production-grade, highly modular, zero-dependency Distributed Object Storage Service implemented in Python. 

### Architectural Overview

```
                      [ Client (cURL / Browser) ]
                                   │
                                   ▼ (PUT / GET / DELETE)
                 ┌───────────────────────────────────┐
                 │           HTTP Gateway            │
                 │ ───────────────────────────────── │
                 │  - Chunked/Striped Stream Router  │
                 │  - Thread-Pool Parallel I/O       │
                 └─────────────────┬─────────────────┘
                                   │
         ┌─────────────────────────┼─────────────────────────┐
         ▼                         ▼                         ▼
┌─────────────────┐       ┌─────────────────┐       ┌─────────────────┐
│Erasure Engine   │       │Metadata Catalog │       │  Storage Nodes  │
│ ─────────────── │       │ ─────────────── │       │ ─────────────── │
│ - GF(2^8) Math  │       │ - Key-Node Map  │       │ - Node 1 (8001) │
│ - Cauchy Matrix │       │ - Stripe State  │       │ - Node 2 (8002) │
│ - Encode/Decode │       │ - Health Status │       │ - ...           │
└─────────────────┘       └─────────────────┘       └─────────────────┘
```

1. **HTTP Gateway**: Streams data block-by-block. It processes incoming data in systematic "stripes" to achieve low-memory footprint uploads and parallelizes fragment distribution to the storage nodes using a thread pool.
2. **Erasure Coding (EC) Engine**: Implements Galois Field $GF(2^8)$ arithmetic and Cauchy-matrix systematic Reed-Solomon coding from scratch. It transforms $k$ data blocks into $m$ parity blocks, ensuring the system can tolerate up to $m$ arbitrary node failures.
3. **Metadata Catalog**: Maintains dynamic mappings of objects, their stripes, checksums, and fragment positions across active storage nodes. It also coordinates active cluster node registrations and status tracking.
4. **Storage Nodes**: Independent, concurrent HTTP endpoints simulating decoupled physical storage devices. They support fragment operations (`PUT`, `GET`, `DELETE`) and failure injection to demonstrate live, self-healing runtime behaviors.

---

### Complete Python Implementation

Save this script as `storage_service.py`. It is complete, self-contained, and runnable out-of-the-box.

```python
import os
import sys
import json
import time
import logging
import hashlib
import threading
from urllib.parse import urlparse, parse_qs
from http.server import HTTPServer, BaseHTTPRequestHandler
import urllib.request
from concurrent.futures import ThreadPoolExecutor, as_completed

# Configure Logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(threadName)s - %(message)s",
    handlers=[logging.StreamHandler(sys.stdout)]
)
logger = logging.getLogger("DistributedStorage")


# =====================================================================
# 1. ERASURE CODING ENGINE (GALOIS FIELD 2^8 & CAUCHY REED-SOLOMON)
# =====================================================================

class GF256:
    """Galois Field GF(2^8) arithmetic using primitive polynomial 285 (0x11d)."""
    PRIM = 0x11d
    EXP = [0] * 512
    LOG = [0] * 256
    _initialized = False

    @classmethod
    def init(cls):
        if cls._initialized:
            return
        x = 1
        for i in range(256):
            cls.EXP[i] = x
            if i < 255:
                cls.LOG[x] = i
            x <<= 1
            if x & 0x100:
                x ^= cls.PRIM
        for i in range(255, 512):
            cls.EXP[i] = cls.EXP[i - 255]
        cls._initialized = True

    @classmethod
    def add(cls, a, b):
        return a ^ b

    @classmethod
    def sub(cls, a, b):
        return a ^ b

    @classmethod
    def mul(cls, a, b):
        if a == 0 or b == 0:
            return 0
        return cls.EXP[cls.LOG[a] + cls.LOG[b]]

    @classmethod
    def inv(cls, a):
        if a == 0:
            raise ZeroDivisionError("Cannot invert zero in GF(2^8)")
        return cls.EXP[255 - cls.LOG[a]]


class GFMatrix:
    """Matrix representation and operations over GF(2^8)."""
    def __init__(self, rows, cols, data=None):
        self.rows = rows
        self.cols = cols
        self.data = data if data else [[0] * cols for _ in range(rows)]

    @classmethod
    def identity(cls, n):
        m = cls(n, n)
        for i in range(n):
            m.data[i][i] = 1
        return m

    def get(self, r, c):
        return self.data[r][c]

    def set(self, r, c, val):
        self.data[r][c] = val

    def invert(self):
        """Invert matrix using Gaussian-Jordan Elimination in GF(2^8)."""
        assert self.rows == self.cols, "Matrix must be square to invert"
        n = self.rows
        aug = [[0] * (2 * n) for _ in range(n)]
        for r in range(n):
            for c in range(n):
                aug[r][c] = self.data[r][c]
            aug[r][n + r] = 1

        for i in range(n):
            pivot_row = i
            while pivot_row < n and aug[pivot_row][i] == 0:
                pivot_row += 1
            if pivot_row == n:
                raise ValueError("Matrix is singular and non-invertible")
            if pivot_row != i:
                aug[i], aug[pivot_row] = aug[pivot_row], aug[i]

            pivot = aug[i][i]
            inv_pivot = GF256.inv(pivot)
            for c in range(2 * n):
                aug[i][c] = GF256.mul(aug[i][c], inv_pivot)

            for r in range(n):
                if r != i:
                    factor = aug[r][i]
                    if factor != 0:
                        for c in range(2 * n):
                            aug[r][c] = GF256.add(aug[r][c], GF256.mul(factor, aug[i][c]))

        inv_data = [[aug[r][c] for c in range(n, 2 * n)] for r in range(n)]
        return GFMatrix(n, n, inv_data)


class ErasureCoder:
    """Reed-Solomon Systematic Cauchy Erasure Coder."""
    def __init__(self, k, m):
        self.k = k
        self.m = m
        GF256.init()
        # Create systematic generator matrix G = [ Identity (k x k) / Cauchy (m x k) ]
        self.G = GFMatrix(k + m, k)
        for i in range(k):
            self.G.set(i, i, 1)
        for i in range(m):
            for j in range(k):
                # Disjoint sets: X_i = i, Y_j = j + m (prevents X_i ^ Y_j = 0)
                denom = GF256.add(i, j + m)
                self.G.set(k + i, j, GF256.inv(denom))

    def encode(self, data_blocks):
        """Encodes k data blocks into k systematic data blocks + m parity blocks."""
        assert len(data_blocks) == self.k
        block_len = len(data_blocks[0])
        encoded = []
        for i in range(self.k + self.m):
            out_block = bytearray(block_len)
            for j in range(self.k):
                coeff = self.G.get(i, j)
                if coeff == 1:
                    for byte_idx in range(block_len):
                        out_block[byte_idx] ^= data_blocks[j][byte_idx]
                elif coeff > 1:
                    for byte_idx in range(block_len):
                        prod = GF256.mul(coeff, data_blocks[j][byte_idx])
                        out_block[byte_idx] ^= prod
            encoded.append(bytes(out_block))
        return encoded

    def decode(self, received_blocks):
        """Decodes at least k received blocks back to the original k data blocks."""
        if len(received_blocks) < self.k:
            raise ValueError(f"Insufficient blocks. Need {self.k}, got {len(received_blocks)}")

        selected_indices = sorted(list(received_blocks.keys()))[:self.k]
        G_sub = GFMatrix(self.k, self.k)
        for r_idx, orig_row_idx in enumerate(selected_indices):
            for c in range(self.k):
                G_sub.set(r_idx, c, self.G.get(orig_row_idx, c))

        G_sub_inv = G_sub.invert()
        block_len = len(received_blocks[selected_indices[0]])
        decoded_data = []

        for r in range(self.k):
            out_block = bytearray(block_len)
            for c in range(self.k):
                coeff = G_sub_inv.get(r, c)
                rec_block = received_blocks[selected_indices[c]]
                if coeff == 1:
                    for byte_idx in range(block_len):
                        out_block[byte_idx] ^= rec_block[byte_idx]
                elif coeff > 1:
                    for byte_idx in range(block_len):
                        prod = GF256.mul(coeff, rec_block[byte_idx])
                        out_block[byte_idx] ^= prod
            decoded_data.append(bytes(out_block))
        return decoded_data


# =====================================================================
# 2. METADATA CATALOG
# =====================================================================

class MetadataCatalog:
    """Thread-safe Registry storing details of key mappings and storage nodes."""
    def __init__(self):
        self.lock = threading.Lock()
        self.objects = {}  # key -> { 'size': int, 'stripes': [ { 'f_idx': node_url, ... } ] }
        self.storage_nodes = {}  # node_id -> { 'url': str, 'status': str }

    def register_node(self, node_id, url):
        with self.lock:
            self.storage_nodes[node_id] = {'url': url, 'status': 'HEALTHY'}
            logger.info(f"Node '{node_id}' registered successfully at {url}")

    def update_node_status(self, node_id, status):
        with self.lock:
            if node_id in self.storage_nodes:
                self.storage_nodes[node_id]['status'] = status
                logger.info(f"Node '{node_id}' status updated to {status}")

    def get_healthy_nodes(self):
        with self.lock:
            return [node_id for node_id, info in self.storage_nodes.items() if info['status'] == 'HEALTHY']

    def get_node_url(self, node_id):
        with self.lock:
            return self.storage_nodes.get(node_id, {}).get('url')

    def record_object(self, key, size, stripes_meta):
        with self.lock:
            self.objects[key] = {
                'size': size,
                'stripes': stripes_meta,
                'timestamp': time.time()
            }
            logger.info(f"Metadata written for key '{key}' ({size} bytes, {len(stripes_meta)} stripes)")

    def get_object_meta(self, key):
        with self.lock:
            return self.objects.get(key)

    def delete_object_meta(self, key):
        with self.lock:
            return self.objects.pop(key, None)


# =====================================================================
# 3. STORAGE NODE SERVICE (HTTP PERSISTENCE INTERFACE)
# =====================================================================

class StorageNodeServer(HTTPServer):
    def __init__(self, server_address, RequestHandlerClass, node_id):
        super().__init__(server_address, RequestHandlerClass)
        self.node_id = node_id
        self.storage = {}  # In-memory "disk" storage (fragment_id -> bytes)
        self.failed = False


class StorageNodeHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        # Suppress verbose standard library HTTP logging
        pass

    def _send_response(self, code, content_type="application/json", payload=b""):
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def do_POST(self):
        # Handle failure simulations
        if self.path == "/simulate-fail":
            self.server.failed = True
            logger.warning(f"[{self.server.node_id}] Failure state INJECTED")
            return self._send_response(200, payload=json.dumps({"status": "Failed State Triggered"}).encode())

        elif self.path == "/simulate-recover":
            self.server.failed = False
            logger.warning(f"[{self.server.node_id}] Failure state CLEARED")
            return self._send_response(200, payload=json.dumps({"status": "Recovered"}).encode())

        if self.server.failed:
            return self._send_response(500, payload=b"Node is simulated OFFLINE")

    def do_PUT(self):
        if self.server.failed:
            return self._send_response(500, payload=b"Node is simulated OFFLINE")

        # PUT /fragments/<fragment_id>
        if self.path.startswith("/fragments/"):
            fragment_id = self.path.split("/")[-1]
            content_length = int(self.headers.get('Content-Length', 0))
            payload = self.rfile.read(content_length)

            self.server.storage[fragment_id] = payload
            return self._send_response(201, payload=json.dumps({"status": "Stored", "size": len(payload)}).encode())

        self._send_response(400, payload=b"Bad Request")

    def do_GET(self):
        if self.server.failed:
            return self._send_response(500, payload=b"Node is simulated OFFLINE")

        # GET /fragments/<fragment_id>
        if self.path.startswith("/fragments/"):
            fragment_id = self.path.split("/")[-1]
            if fragment_id in self.server.storage:
                return self._send_response(200, "application/octet-stream", self.server.storage[fragment_id])
            else:
                return self._send_response(404, payload=b"Fragment Not Found")

        self._send_response(400, payload=b"Bad Request")

    def do_DELETE(self):
        if self.server.failed:
            return self._send_response(500, payload=b"Node is simulated OFFLINE")

        # DELETE /fragments/<fragment_id>
        if self.path.startswith("/fragments/"):
            fragment_id = self.path.split("/")[-1]
            if fragment_id in self.server.storage:
                del self.server.storage[fragment_id]
                return self._send_response(200, payload=b"Fragment Deleted")
            return self._send_response(404, payload=b"Fragment Not Found")

        self._send_response(400, payload=b"Bad Request")


# =====================================================================
# 4. HTTP GATEWAY (COORDINATOR, STRIPING ENGINE, PARALLEL I/O)
# =====================================================================

class HTTPGatewayHandler(BaseHTTPRequestHandler):
    # Constants for Erasure Coding Striping
    K = 4
    M = 2
    BLOCK_SIZE = 16384  # 16 KB stripes
    STRIPE_SIZE = K * BLOCK_SIZE  # 64 KB input chunks

    coder = ErasureCoder(K, M)
    catalog = MetadataCatalog()
    thread_pool = ThreadPoolExecutor(max_workers=16, thread_name_prefix="GatewayIO")

    def log_message(self, format, *args):
        pass

    def _send_response(self, code, content_type="application/json", payload=b""):
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def do_GET(self):
        parsed = urlparse(self.path)
        path_parts = [p for p in parsed.path.split('/') if p]

        # GET /status
        if len(path_parts) == 1 and path_parts[0] == "status":
            status_data = {
                "nodes": self.catalog.storage_nodes,
                "objects": self.catalog.objects
            }
            return self._send_response(200, payload=json.dumps(status_data, indent=2).encode())

        # GET /objects/<key>
        if len(path_parts) == 2 and path_parts[0] == "objects":
            key = path_parts[1]
            meta = self.catalog.get_object_meta(key)
            if not meta:
                return self._send_response(404, payload=b"Object Key Not Found")

            self.send_response(200)
            self.send_header("Content-Type", "application/octet-stream")
            self.send_header("Content-Length", str(meta['size']))
            self.end_headers()

            remaining_bytes = meta['size']

            for stripe_idx, stripe in enumerate(meta['stripes']):
                # Attempt to retrieve fragments in parallel
                retrieved_fragments = {}

                def fetch_fragment(f_idx, node_id, frag_id, expected_hash):
                    url = self.catalog.get_node_url(node_id)
                    req = urllib.request.Request(f"{url}/fragments/{frag_id}", method="GET")
                    try:
                        with urllib.request.urlopen(req, timeout=1.0) as res:
                            data = res.read()
                            if hashlib.md5(data).hexdigest() == expected_hash:
                                return f_idx, data
                            logger.error(f"Integrity failure on fragment {frag_id} from {node_id}")
                    except Exception as e:
                        logger.warning(f"Failed fetching fragment {frag_id} from {node_id}: {e}")
                    return None

                futures = []
                for f_idx_str, frag in stripe.items():
                    f_idx = int(f_idx_str)
                    futures.append(self.thread_pool.submit(
                        fetch_fragment, f_idx, frag['node_id'], frag['fragment_id'], frag['hash']
                    ))

                for fut in as_completed(futures):
                    result = fut.result()
                    if result:
                        f_idx, data = result
                        retrieved_fragments[f_idx] = data

                if len(retrieved_fragments) < self.K:
                    logger.critical(f"UNRECOVERABLE LOSS: Key '{key}', Stripe {stripe_idx}")
                    # We send closed connection behavior or abort midway since headers already sent
                    return

                # Decode the stripe
                decoded_stripe = self.coder.decode(retrieved_fragments)
                stripe_bytes = b"".join(decoded_stripe)

                # Truncate final block if it's the last stripe
                bytes_to_write = min(remaining_bytes, len(stripe_bytes))
                self.wfile.write(stripe_bytes[:bytes_to_write])
                remaining_bytes -= bytes_to_write

            return

        self._send_response(404, payload=b"Not Found")

    def do_PUT(self):
        parsed = urlparse(self.path)
        path_parts = [p for p in parsed.path.split('/') if p]

        # PUT /objects/<key>
        if len(path_parts) == 2 and path_parts[0] == "objects":
            key = path_parts[1]
            content_length = int(self.headers.get('Content-Length', 0))
            if content_length == 0:
                return self._send_response(400, payload=b"Content-Length required")

            healthy_nodes = self.catalog.get_healthy_nodes()
            total_required = self.K + self.M
            if len(healthy_nodes) < total_required:
                return self._send_response(503, payload=b"Insufficient Healthy Storage Nodes available")

            stripes_meta = []
            bytes_processed = 0

            # Read and process chunked streams
            while bytes_processed < content_length:
                # Read 1 Full Stripe of size (K * BLOCK_SIZE)
                chunk_to_read = min(self.STRIPE_SIZE, content_length - bytes_processed)
                stripe_data = self.rfile.read(chunk_to_read)
                bytes_processed += len(stripe_data)

                # Pad last chunk to maintain consistent block alignments
                pad_len = self.STRIPE_SIZE - len(stripe_data)
                if pad_len > 0:
                    stripe_data += b"\x00" * pad_len

                # Slices into systematic k pieces
                data_blocks = [
                    stripe_data[i * self.BLOCK_SIZE: (i + 1) * self.BLOCK_SIZE] 
                    for i in range(self.K)
                ]

                # Compute parity
                encoded_blocks = self.coder.encode(data_blocks)

                # Select Target Nodes using a deterministic rotating offset per stripe index (Load Balancing)
                stripe_idx = len(stripes_meta)
                target_nodes = [
                    healthy_nodes[(stripe_idx + offset) % len(healthy_nodes)]
                    for offset in range(total_required)
                ]

                # Distribute fragments in parallel
                stripe_descriptor = {}

                def upload_fragment(f_idx, node_id, block):
                    frag_id = f"{key}_s{stripe_idx}_f{f_idx}"
                    url = self.catalog.get_node_url(node_id)
                    req = urllib.request.Request(
                        f"{url}/fragments/{frag_id}", 
                        data=block, 
                        method="PUT",
                        headers={"Content-Type": "application/octet-stream"}
                    )
                    try:
                        with urllib.request.urlopen(req, timeout=1.0) as res:
                            if res.status == 201:
                                return f_idx, {
                                    "node_id": node_id,
                                    "fragment_id": frag_id,
                                    "hash": hashlib.md5(block).hexdigest()
                                }
                    except Exception as e:
                        logger.error(f"Failed sending fragment {frag_id} to node {node_id}: {e}")
                    return None

                futures = []
                for f_idx, node_id in enumerate(target_nodes):
                    futures.append(self.thread_pool.submit(
                        upload_fragment, f_idx, node_id, encoded_blocks[f_idx]
                    ))

                for fut in as_completed(futures):
                    result = fut.result()
                    if result:
                        f_idx, item = result
                        stripe_descriptor[f_idx] = item

                # Safety check: Did all k+m writes complete? 
                if len(stripe_descriptor) < total_required:
                    # Clean up partial allocations
                    logger.error(f"Stripe {stripe_idx} upload failed. Incomplete fragments written.")
                    return self._send_response(500, payload=b"Failed writing required erasure stripes")

                stripes_meta.append(stripe_descriptor)

            # Record final properties inside state tracking Catalog
            self.catalog.record_object(key, content_length, stripes_meta)
            return self._send_response(201, payload=json.dumps({"status": "Uploaded", "key": key, "size": content_length}).encode())

        self._send_response(400, payload=b"Bad Request")

    def do_POST(self):
        parsed = urlparse(self.path)
        path_parts = [p for p in parsed.path.split('/') if p]

        # POST /objects/<key>/heal
        if len(path_parts) == 3 and path_parts[0] == "objects" and path_parts[2] == "heal":
            key = path_parts[1]
            meta = self.catalog.get_object_meta(key)
            if not meta:
                return self._send_response(404, payload=b"Object Key Not Found")

            logger.info(f"Initiating Self-Healing Routine for '{key}'...")
            healthy_nodes = self.catalog.get_healthy_nodes()
            healed_count = 0

            for stripe_idx, stripe in enumerate(meta['stripes']):
                retrieved_fragments = {}
                missing_indices = []

                # Audit existing fragments on nodes
                for f_idx_str, frag in stripe.items():
                    f_idx = int(f_idx_str)
                    url = self.catalog.get_node_url(frag['node_id'])

                    # Test reachability and integrity
                    is_valid = False
                    try:
                        req = urllib.request.Request(f"{url}/fragments/{frag['fragment_id']}", method="GET")
                        with urllib.request.urlopen(req, timeout=1.0) as res:
                            data = res.read()
                            if hashlib.md5(data).hexdigest() == frag['hash']:
                                retrieved_fragments[f_idx] = data
                                is_valid = True
                    except Exception:
                        pass

                    if not is_valid:
                        missing_indices.append(f_idx)

                if not missing_indices:
                    continue  # Stripe healthy, skip

                logger.info(f"Stripe {stripe_idx} compromised. Missing indexes: {missing_indices}")

                if len(retrieved_fragments) < self.K:
                    logger.critical(f"Unrecoverable state. Cannot heal stripe {stripe_idx}.")
                    return self._send_response(500, payload=b"Stripe beyond maximum recovery threshold")

                # Restore missing segments using Reed-Solomon math
                decoded = self.coder.decode(retrieved_fragments)
                re_encoded_stripe = self.coder.encode(decoded)

                # Re-upload missing shards to alternative/re-established healthy nodes
                for f_idx in missing_indices:
                    # Allocate next healthy node that is not already hosting a fragment for this stripe
                    already_assigned_nodes = {frag['node_id'] for frag in stripe.values() if int(frag_id_idx) != f_idx}
                    candidate_nodes = [n for n in healthy_nodes if n not in already_assigned_nodes]

                    if not candidate_nodes:
                        return self._send_response(503, payload=b"No alternative safe target nodes found to heal block")

                    chosen_node = candidate_nodes[0]
                    frag_id = f"{key}_s{stripe_idx}_f{f_idx}"
                    target_url = self.catalog.get_node_url(chosen_node)
                    block_data = re_encoded_stripe[f_idx]

                    # Push healed block
                    req = urllib.request.Request(
                        f"{target_url}/fragments/{frag_id}", 
                        data=block_data, 
                        method="PUT",
                        headers={"Content-Type": "application/octet-stream"}
                    )
                    try:
                        with urllib.request.urlopen(req, timeout=1.0) as res:
                            if res.status == 201:
                                # Update catalog records
                                stripe[str(f_idx)] = {
                                    "node_id": chosen_node,
                                    "fragment_id": frag_id,
                                    "hash": hashlib.md5(block_data).hexdigest()
                                }
                                healed_count += 1
                                logger.info(f"Healed and synced index {f_idx} for stripe {stripe_idx} onto {chosen_node}")
                    except Exception as e:
                        logger.error(f"Failed uploading healed fragment {frag_id} to {chosen_node}: {e}")
                        return self._send_response(500, payload=b"Failed executing heal replication steps")

            return self._send_response(200, payload=json.dumps({"status": "Success", "healed_fragments": healed_count}).encode())

        # DELETE /objects/<key>
        if len(path_parts) == 2 and path_parts[0] == "objects":
            key = path_parts[1]
            meta = self.catalog.delete_object_meta(key)
            if not meta:
                return self._send_response(404, payload=b"Object Key Not Found")

            # Remove chunks from backing instances asynchronously
            def purge_fragment(node_id, frag_id):
                url = self.catalog.get_node_url(node_id)
                req = urllib.request.Request(f"{url}/fragments/{frag_id}", method="DELETE")
                try:
                    with urllib.request.urlopen(req, timeout=1.0) as r:
                        return r.status == 200
                except Exception:
                    return False

            for stripe in meta['stripes']:
                for frag in stripe.values():
                    self.thread_pool.submit(purge_fragment, frag['node_id'], frag['fragment_id'])

            logger.info(f"Purge request completed for object '{key}'")
            return self._send_response(200, payload=json.dumps({"status": "Purged", "key": key}).encode())

        self._send_response(400, payload=b"Bad Request")


