# 5. AUTOMATED LIVE CLUSTER DEMONSTRATION & INTEGRATION TESTS
# =====================================================================

def run_cluster_test():
    """Spin up local topology, orchestrate failures, verify math consistency."""
    # Instantiates storage servers
    node_ports = {
        "node_1": 8001,
        "node_2": 8002,
        "node_3": 8003,
        "node_4": 8004,
        "node_5": 8005,
        "node_6": 8006,
    }

    servers = {}
    threads = []

    logger.info("Initializing Storage Cluster...")
    for node_id, port in node_ports.items():
        srv = StorageNodeServer(("127.0.0.1", port), StorageNodeHandler, node_id)
        servers[node_id] = srv
        t = threading.Thread(target=srv.serve_forever, daemon=True, name=node_id)
        t.start()
        threads.append(t)
        # Register in Gateway's Catalog
        HTTPGatewayHandler.catalog.register_node(node_id, f"http://127.0.0.1:{port}")

    # Launch Gateway Control Plane
    gateway_port = 8000
    gateway_srv = HTTPServer(("127.0.0.1", gateway_port), HTTPGatewayHandler)
    gateway_thread = threading.Thread(target=gateway_srv.serve_forever, daemon=True, name="Gateway")
    gateway_thread.start()
    logger.info(f"Gateway Coordinator listening on http://127.0.0.1:{gateway_port}")

    time.sleep(1.0)  # Allow sockets to bind

    try:
        # Generate raw diagnostic test content
        original_data = b"Distributed Systems Course Assignment: Reed-Solomon storage engine verification! " * 1000
        test_key = "system_validation_doc.bin"

        logger.info(f"Initiating Upload for '{test_key}' (Size: {len(original_data)} bytes)...")

        # 1. Test Gateway Systematic Chunked Upload
        req = urllib.request.Request(
            f"http://127.0.0.1:{gateway_port}/objects/{test_key}",
            data=original_data,
            method="PUT",
            headers={"Content-Length": str(len(original_data)), "Content-Type": "application/octet-stream"}
        )
        with urllib.request.urlopen(req) as res:
            logger.info(f"Upload Response: {res.read().decode().strip()}")

        # 2. Test Lossless Reconstruction (Healthy State)
        logger.info("Verifying standard download capabilities...")
        with urllib.request.urlopen(f"http://127.0.0.1:{gateway_port}/objects/{test_key}") as res:
            retrieved = res.read()
            assert retrieved == original_data, "Data Integrity Mismatch during basic restoration!"
        logger.info("Reconstructed file matches binary source exactly! (Integrity: 100% Correct)")

        # 3. Simulate Failures (Injecting Maximum Fault Threshold: M=2 Offline Nodes)
        failed_nodes = ["node_2", "node_5"]
        logger.warning(f"Injecting failure events on nodes: {failed_nodes}")
        for nid in failed_nodes:
            # Trigger failed state route in the node
            url = HTTPGatewayHandler.catalog.get_node_url(nid)
            req = urllib.request.Request(f"{url}/simulate-fail", method="POST")
            urllib.request.urlopen(req)
            # Update catalog state
            HTTPGatewayHandler.catalog.update_node_status(nid, "DOWN")

        # 4. Attempt Download (Active Fault Tolerance Mode)
        logger.info(f"Downloading while 2 nodes are offline (using Cauchy Reed-Solomon decoding)...")
        with urllib.request.urlopen(f"http://127.0.0.1:{gateway_port}/objects/{test_key}") as res:
            retrieved_under_fault = res.read()
            assert retrieved_under_fault == original_data, "Fault tolerance reconstruction failed to yield identical data!"
        logger.info("Successfully bypassed 2 node failures! Cauchy erasure recovery validated.")

        # 5. Restore Failed Devices & Initiate Dynamic Self-Healing
        logger.info("Bringing failed storage instances back online...")
        for nid in failed_nodes:
            url = HTTPGatewayHandler.catalog.get_node_url(nid)
            req = urllib.request.Request(f"{url}/simulate-recover", method="POST")
            urllib.request.urlopen(req)
            HTTPGatewayHandler.catalog.update_node_status(nid, "HEALTHY")

        logger.info("Executing API Self-Healing Scrubber...")
        heal_req = urllib.request.Request(f"http://127.0.0.1:{gateway_port}/objects/{test_key}/heal", method="POST")
        with urllib.request.urlopen(heal_req) as res:
            logger.info(f"Healing Scrubber Report: {res.read().decode().strip()}")

        # 6. Verify file remains accessible post-recovery
        with urllib.request.urlopen(f"http://127.0.0.1:{gateway_port}/objects/{test_key}") as res:
            retrieved_post_heal = res.read()
            assert retrieved_post_heal == original_data, "Post-heal retrieval yielded invalid payload!"
        logger.info("Dynamic self-healing verified. Object storage cluster is now in a consistent, healthy state!")

    finally:
        logger.info("Shutting down Storage Cluster services...")
        gateway_srv.shutdown()
        for srv in servers.values():
            srv.shutdown()
        logger.info("Cluster destroyed cleanly.")


if __name__ == "__main__":
    run_cluster_test()
